insert into public.diagnostico_items
  (id, area, tipo, peso, elo, elo_base, enunciado, opciones, fen, correcta, solucion, alternas, explica, lichess, rating)
values
  ('cal_lx_0IVo3_op', 'calculo', 'opcion_tablero', 1, 273, 433, 'Las negras acaban de jugar …cxd2. Juegan las blancas y están en apuros. Solo una de estas jugadas salva la partida: ¿cuál?', '["Txc7","Txb4","Td1","Tf1"]'::jsonb, '3r1rk1/2q1b1pp/4pn2/1Q6/1p6/4P1P1/3p1PBP/1RR3K1 w - - 0 28', 0, null, null, 'Hay algo sin defender, y hay que verlo antes que el rival. La línea: 28.Txc7 d1=T+ 29.Txd1 Txd1+ 30.Af1. Las otras tientan, pero fallan: Txb4? se contesta con 28…dxc1=D+ y las negras quedan mejor; Td1? se contesta con 28…Dc2 y las negras quedan mejor; Tf1? se contesta con 28…Rh8 y las negras quedan mejor.', '0IVo3', 983),
  ('cal_lx_0JHet_op', 'calculo', 'opcion_tablero', 1, 920, 1080, 'Las negras acaban de jugar …Dc5. Juegan las blancas y están en apuros. Solo una de estas jugadas salva la partida: ¿cuál?', '["b4","Axf7+","Axb7","Dxa6"]'::jsonb, '2r2rk1/1p3p1p/p5pb/n1qBp3/3pP3/P2Q2PP/1P3PN1/R4RK1 w - - 4 23', 0, null, null, 'Es un tenedor: una pieza ataca dos objetivos a la vez. La línea: 23.b4 Dc3 24.Dxc3 dxc3 25.bxa5. Las otras tientan, pero fallan: Axf7+? se contesta con 23…Txf7 y las negras quedan mejor; Axb7? se contesta con 23…Cxb7 y las negras quedan mejor; Dxa6? se contesta con 23…bxa6 y las negras quedan mejor.', '0JHet', 1630),
  ('cal_lx_1FlQw', 'calculo', 'jugada', 1, 505, 885, 'Las negras acaban de jugar …Txd1. Juegan las blancas y fuerzan el mate. ¿Cuál es la primera jugada? (Se responde con una sola jugada.)', null, '4r1k1/p4ppp/8/2q5/8/1Q6/PP4PP/3r1R1K w - - 0 22', null, '{"from":"b3","to":"f7"}'::jsonb, null, 'Es un tenedor: una pieza ataca dos objetivos a la vez. La línea: 22.Dxf7+ Rh8 23.Dxe8+ Df8 24.Dxf8#.', '1FlQw', 1285),
  ('cal_lx_1dUup_op', 'calculo', 'opcion_tablero', 1, 656, 816, 'Las negras acaban de jugar …Rxf7. Juegan las blancas. Solo una de estas jugadas gana: ¿cuál?', '["Dxc5","Dxf6+","Dc7+","Dd7+"]'::jsonb, '4r3/1q3kbp/1p1Q1np1/pNr5/P1P1p3/1P6/5PPP/2R2RK1 w - - 0 26', 0, null, null, 'Es un tenedor: una pieza ataca dos objetivos a la vez. La línea: 26.Dxc5 bxc5 27.Cd6+ Rg8 28.Cxb7. Las otras tientan, pero fallan: Dxf6+? se contesta con 26…Rxf6 y las negras quedan mejor; Dc7+? se contesta con 26…Dxc7 y las negras quedan mejor; Dd7+? se contesta con 26…Dxd7 y las negras quedan mejor.', '1dUup', 1366),
  ('cal_lx_1gc7t', 'calculo', 'jugada', 1, 512, 892, 'Las negras acaban de jugar …Txf5. Juegan las blancas y fuerzan el mate. ¿Cuál es la primera jugada? (Se responde con una sola jugada.)', null, '6k1/2p2pp1/p2b4/1pp2rBQ/2q5/7P/PP2R1K1/8 w - - 0 36', null, '{"from":"e2","to":"e8"}'::jsonb, null, 'Es una atracción: se arrastra a una pieza (a menudo el rey) a una casilla fatal. La línea: 36.Te8+ Af8 37.Txf8+ Rxf8 38.Dh8#.', '1gc7t', 1292),
  ('cal_lx_2WCyn', 'calculo', 'jugada', 1, 663, 1043, 'Las negras acaban de jugar …Df3+. Juegan las blancas y están en apuros: encuentra la única jugada que no pierde.', null, 'r1b2k2/6bQ/p3p1BP/1p1pP3/8/5qB1/8/1N5K w - - 1 33', null, '{"from":"h1","to":"h2"}'::jsonb, null, 'Una pieza rival queda atrapada, sin casilla adonde ir. La línea: 33.Rh2 Ta7 34.hxg7+ Txg7 35.Dh8+.', '2WCyn', 1443),
  ('cal_lx_2WvX1_op', 'calculo', 'opcion_tablero', 1, 809, 969, 'Las negras acaban de jugar …Dh6. Juegan las blancas y están en apuros. Solo una de estas jugadas salva la partida: ¿cuál?', '["g5","Dxa6","f6","a3"]'::jsonb, '2r2rk1/1p3ppp/p2p3q/2b1pP2/4P1P1/2N3PN/PPn3BK/R4Q2 w - - 2 19', 0, null, null, 'Una pieza rival queda atrapada, sin casilla adonde ir. La línea: 19.g5 Dh5 20.Af3 Dxf3 21.Dxf3. Las otras tientan, pero fallan: Dxa6? se contesta con 19…bxa6 y las negras quedan mejor; f6? se contesta con 19…Dxf6 y las negras quedan mejor; a3? se contesta con 19…f6 y las negras quedan mejor.', '2WvX1', 1519),
  ('cal_lx_2XstJ', 'calculo', 'jugada', 1, 416, 796, 'Las negras acaban de jugar …Cf6. Juegan las blancas y están en apuros: encuentra la única jugada que no pierde.', null, '2k4r/pp3ppp/3rpn2/4qb2/8/2N5/PP2BPPP/R1Q1K2R w KQ - 2 15', null, '{"from":"c3","to":"b5"}'::jsonb, null, 'Es un ataque a la descubierta: al moverse una pieza, se destapa otra. La línea: 15.Cb5+ Tc6 16.Cxa7+ Rd7 17.Cxc6.', '2XstJ', 1196),
  ('cal_lx_0a1yP', 'calculo', 'jugada', 1, 970, 1370, 'Las negras acaban de jugar …Txf4. Juegan las blancas y están en apuros: encuentra la única jugada que no pierde.', null, 'r4qk1/pp2n3/3p4/3P2pp/2B1pr1P/6Q1/PPP3KP/5R2 w - - 0 28', null, '{"from":"g3","to":"g5"}'::jsonb, null, 'La línea: 28.Dxg5+ Dg7 29.Dxg7+ Rxg7 30.Txf4.', '0a1yP', 1770),
  ('cal_lx_2BNXi', 'calculo', 'jugada', 1, 920, 1302, 'Las negras acaban de jugar …Rh8. Juegan las blancas. Encuentra la jugada que gana (se responde con una sola jugada).', null, 'r6k/pp2pr1p/3p1p1Q/2p2NR1/4P3/1P1P4/P1P1nq2/6RK w - - 1 31', null, '{"from":"g5","to":"g7"}'::jsonb, null, 'La línea: 31.Tg7 Dxg1+ 32.Txg1 Cxg1 33.Rxg1.', '2BNXi', 1702),
  ('cal_lx_3F8sW', 'calculo', 'jugada', 1, 1000, 1380, 'Las negras acaban de jugar …Cxc3. Juegan las blancas y fuerzan el mate. ¿Cuál es la primera jugada? (Se responde con una sola jugada.)', null, 'r1b2rk1/pp3ppp/8/1q2p3/6nP/1Nn2Q2/PPP3P1/2KR1R2 w - - 0 20', null, '{"from":"f3","to":"f7"}'::jsonb, null, 'Hay un sacrificio: se entrega material para ganar más. La línea: 20.Dxf7+ Txf7 21.Td8+ De8 22.Txe8+.', '3F8sW', 1780),
  ('cal_lx_3SbfG_op', 'calculo', 'opcion_tablero', 2, 1140, 1321, 'Las negras acaban de jugar …Cxe4. Juegan las blancas. ¿Cuál de estas jugadas fuerza el mate?', '["Dxh7+","Dxg6+","Txg6+","Dxd5"]'::jsonb, '2r2rk1/1pq2p1p/p2p1Bp1/3p3Q/P1P1n3/1P4R1/5PPP/R5K1 w - - 0 21', 0, null, null, 'Es una atracción: se arrastra a una pieza (a menudo el rey) a una casilla fatal. La línea: 21.Dxh7+ Rxh7 22.Th3+ Rg8 23.Th8#. Las otras tientan, pero fallan: Dxg6+? se contesta con 21…fxg6 y las negras quedan mejor; Txg6+? se contesta con 21…fxg6 y las negras quedan mejor; Dxd5? se contesta con 21…Cxf6 y las negras quedan mejor.', '3SbfG', 1871),
  ('cal_lx_3UDPm', 'calculo', 'jugada', 1, 870, 1254, 'Las negras acaban de jugar …Db6. Juegan las blancas y están en apuros: encuentra la única jugada que no pierde.', null, 'rn3rk1/pp1b1pbp/1q1p1np1/1B4B1/P2Q4/2N1P2P/1PP2PP1/R3K2R w KQ - 3 12', null, '{"from":"g5","to":"f6"}'::jsonb, null, 'La línea: 12.Axf6 Dxd4 13.Axd4 Axd4 14.exd4.', '3UDPm', 1654),
